CREATE FUNCTION public.company_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.client_id IS DISTINCT FROM OLD.client_id THEN RAISE EXCEPTION 'Company cannot be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER accounts_company_immutable BEFORE UPDATE ON public.accounts FOR EACH ROW EXECUTE FUNCTION public.company_immutable();
CREATE TRIGGER contacts_company_immutable BEFORE UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION public.company_immutable();
CREATE TRIGGER folders_company_immutable BEFORE UPDATE ON public.doc_folders FOR EACH ROW EXECUTE FUNCTION public.company_immutable();
CREATE TRIGGER documents_company_immutable BEFORE UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.company_immutable();
CREATE FUNCTION public.account_parent_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.parent_id IS NOT NULL AND (NEW.parent_id=NEW.id OR NOT EXISTS(SELECT 1 FROM public.accounts WHERE id=NEW.parent_id AND client_id=NEW.client_id)) THEN RAISE EXCEPTION 'Invalid parent account'; END IF; RETURN NEW; END $$;
CREATE TRIGGER accounts_parent BEFORE INSERT OR UPDATE ON public.accounts FOR EACH ROW EXECUTE FUNCTION public.account_parent_guard();
CREATE FUNCTION public.folder_parent_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.parent_id IS NOT NULL AND (NEW.parent_id=NEW.id OR NOT EXISTS(SELECT 1 FROM public.doc_folders WHERE id=NEW.parent_id AND client_id=NEW.client_id)) THEN RAISE EXCEPTION 'Invalid parent folder'; END IF; RETURN NEW; END $$;
CREATE TRIGGER folders_parent BEFORE INSERT OR UPDATE ON public.doc_folders FOR EACH ROW EXECUTE FUNCTION public.folder_parent_guard();
CREATE OR REPLACE FUNCTION public.document_client_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.has_company_access(OLD.client_id) AND ((to_jsonb(NEW)-'original_filename'-'folder_id'-'deleted_at') IS DISTINCT FROM (to_jsonb(OLD)-'original_filename'-'folder_id'-'deleted_at')) THEN RAISE EXCEPTION 'Only document names and folders can be edited'; END IF; IF NEW.folder_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.doc_folders WHERE id=NEW.folder_id AND client_id=NEW.client_id) THEN RAISE EXCEPTION 'Invalid folder'; END IF; RETURN NEW; END $$;
CREATE POLICY profiles_tenant ON public.profiles AS RESTRICTIVE FOR SELECT TO authenticated USING(id=auth.uid() OR (client_id IS NOT NULL AND (public.has_company_access(client_id) OR public.is_company_client(client_id))) OR EXISTS(SELECT 1 FROM public.firm_members mine WHERE mine.user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.firm_members other WHERE other.user_id=profiles.id AND other.firm_id=mine.firm_id)));
CREATE POLICY roles_tenant ON public.user_roles AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=user_roles.user_id));
CREATE OR REPLACE FUNCTION public.my_client_id(_user_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.client_id FROM public.profiles p JOIN public.client_access a ON a.client_id=p.client_id AND a.user_id=p.id WHERE p.id=_user_id AND p.status='active' AND a.status='approved' AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=_user_id AND r.role='client') $$;
CREATE POLICY company_profile_client ON public.profiles FOR SELECT TO authenticated USING(public.is_company_client(client_id));
CREATE FUNCTION public.journal_contact_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.contact_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.contacts WHERE id=NEW.contact_id AND client_id=NEW.client_id AND is_active) THEN RAISE EXCEPTION 'Contact belongs to another company or is inactive'; END IF; RETURN NEW; END $$;
CREATE TRIGGER journal_contact BEFORE INSERT ON public.journal_lines FOR EACH ROW EXECUTE FUNCTION public.journal_contact_guard();
CREATE POLICY txns_visible ON public.transactions AS RESTRICTIVE FOR SELECT TO authenticated USING(deleted_at IS NULL AND (entry_id IS NULL OR EXISTS(SELECT 1 FROM public.journal_entries j WHERE j.id=entry_id AND NOT j.voided)));
CREATE POLICY documents_visible ON public.documents AS RESTRICTIVE FOR SELECT TO authenticated USING(deleted_at IS NULL);
CREATE FUNCTION public.company_settings_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.firm_id IS DISTINCT FROM OLD.firm_id THEN RAISE EXCEPTION 'Firm cannot be changed'; END IF; IF NEW.fiscal_year_start<1 OR NEW.fiscal_year_start>12 OR NEW.accounting_method NOT IN('cash','accrual') OR NEW.base_currency NOT IN('USD','CAD','EUR','GBP') THEN RAISE EXCEPTION 'Invalid accounting settings'; END IF; RETURN NEW; END $$;
CREATE TRIGGER company_settings BEFORE UPDATE ON public.clients FOR EACH ROW EXECUTE FUNCTION public.company_settings_guard();